func:
if (global.get('SYSTEM_SHUTDOWN')) {
    node.status({fill:'red',shape:'ring',text:'SHUTDOWN'});
    return null;
}
const base = (global.get('LEADS_URL') || env.get('LEADS_PUBLIC_URL') || env.get('DASHBOARD_PUBLIC_URL') || 'https://leads.shamrockbailbonds.biz').replace(/\/$/, '');
msg.url = base + '/api/automation/osint-hot-leads';
const apiKey = global.get('GAS_API_KEY') || env.get('GAS_API_KEY') || '';
msg.headers = {
    'Content-Type': 'application/json',
    'X-API-Key': apiKey,
    'X-Api-Key': apiKey
};
msg.payload = {
    hours_back: 24,
    min_score: 70,
    limit: 5,
    deep_scan: false,
    second_opinion: false,
    dry_run: false
};
msg.method = 'POST';
msg._osint = { startedAt: new Date().toISOString() };
node.status({fill:'blue',shape:'dot',text:'Queueing OSINT…'});
return msg;

const data = msg.payload || {};
const c = data.counts || {};
const queued = data.queued || [];
const ok = data.ok !== false;

if (!ok) {
    msg.headers = {
        Authorization: 'Bearer ' + (global.get('SLACK_TOKEN') || global.get('SLACK_BOT_TOKEN') || env.get('SLACK_BOT_TOKEN') || ''),
        'Content-Type': 'application/json; charset=utf-8'
    };
    msg.payload = {
        channel: global.get('SLACK_CHANNEL_ERRORS') || '#scraper-errors',
        text: '⚠️ *OSINT Hot Leads failed*\n' + (data.error || JSON.stringify(data).slice(0, 300))
    };
    msg.url = 'https://slack.com/api/chat.postMessage';
    node.status({fill:'red',shape:'dot',text:'failed'});
    return [msg, null];
}

const q = c.queued || 0;
if (q === 0) {
    node.status({fill:'green',shape:'ring',text:'Quiet — 0 queued'});
    return [null, msg];
}

const lines = queued.slice(0, 5).map(x =>
    `• score=${x.lead_score || '?'} ${x.county || ''} report=${(x.report_id || '').slice(-6)} email=${x.has_email ? 'y' : 'n'}`
).join('\n');

const text = [
    '🔍 *OSINT Hot Leads*',
    `Hot window: ${c.hot_scanned || 0} · candidates: ${c.candidates || 0} · queued: ${q}`,
    `Skipped recent OSINT: ${c.skipped_recent_osint || 0} · no id: ${c.skipped_no_identifier || 0}`,
    '',
    '*Queued (Maigret default · Blackbird if email)*',
    lines || '_None_',
    '',
    '_Risk scores are advisory only._'
].join('\n');

msg.headers = {
    Authorization: 'Bearer ' + (global.get('SLACK_TOKEN') || global.get('SLACK_BOT_TOKEN') || env.get('SLACK_BOT_TOKEN') || ''),
    'Content-Type': 'application/json; charset=utf-8'
};
msg.payload = {
    channel: global.get('SLACK_CHANNEL_LEADS') || '#leads',
    text: text
};
msg.url = 'https://slack.com/api/chat.postMessage';
node.status({fill:'green',shape:'dot',text:`Queued ${q}`});
return [msg, null];

if (global.get('SYSTEM_SHUTDOWN')) {
    node.status({fill:'red',shape:'ring',text:'SHUTDOWN'});
    return null;
}
const base = (global.get('LEADS_URL') || env.get('LEADS_PUBLIC_URL') || env.get('DASHBOARD_PUBLIC_URL') || 'https://leads.shamrockbailbonds.biz').replace(/\/$/, '');
msg.url = base + '/api/automation/osint-status';
const apiKey = global.get('GAS_API_KEY') || env.get('GAS_API_KEY') || '';
msg.headers = {
    'Content-Type': 'application/json',
    'X-API-Key': apiKey,
    'X-Api-Key': apiKey
};
msg.payload = {};
msg.method = 'GET';
node.status({fill:'blue',shape:'dot',text:'Probing worker…'});
return msg;

const data = msg.payload || {};
const ready = !!data.ready_for_scans;
const reach = data.worker_reachable !== false;
const m = (data.maigret || {}).available;
const b = (data.blackbird || {}).available;

if (ready && reach) {
    node.status({fill:'green',shape:'dot',text:`OK M=${m?'y':'n'} B=${b?'y':'n'}`});
    return [null, msg];
}

msg.headers = {
    Authorization: 'Bearer ' + (global.get('SLACK_TOKEN') || global.get('SLACK_BOT_TOKEN') || env.get('SLACK_BOT_TOKEN') || ''),
    'Content-Type': 'application/json; charset=utf-8'
};
msg.payload = {
    channel: global.get('SLACK_CHANNEL_ERRORS') || '#scraper-errors',
    text: [
        '🚨 *OSINT Worker unhealthy*',
        `reachable=${reach} ready=${ready}`,
        `maigret=${m} blackbird=${b}`,
        data.error || (data.maigret && data.maigret.error) || ''
    ].filter(Boolean).join('\n')
};
msg.url = 'https://slack.com/api/chat.postMessage';
node.status({fill:'red',shape:'dot',text:'worker down'});
return [msg, null];

if (global.get('SYSTEM_SHUTDOWN')) {
    node.status({fill:'red',shape:'ring',text:'SHUTDOWN'});
    return null;
}
const base = (global.get('LEADS_URL') || env.get('LEADS_PUBLIC_URL') || env.get('DASHBOARD_PUBLIC_URL') || 'https://leads.shamrockbailbonds.biz').replace(/\/$/, '');
msg.url = base + '/api/automation/ops-digest';
const apiKey = global.get('GAS_API_KEY') || env.get('GAS_API_KEY') || '';
msg.headers = {
    'Content-Type': 'application/json',
    'X-API-Key': apiKey,
    'X-Api-Key': apiKey
};
msg.payload = { hours_back: 24, post_slack: true };
msg.method = 'POST';
node.status({fill:'blue',shape:'dot',text:'Ops digest…'});
return msg;

const d = msg.payload || {};
const ok = d.ok !== false;
const text = [
    '📋 *Ops Digest*',
    `Hot leads 24h: ${d.hot_leads_24h ?? '—'}`,
    `Active bonds: ${d.active_bonds ?? '—'} · missing court: ${d.missing_court_date ?? '—'}`,
    `Forfeiture flags: ${d.forfeiture_flags ?? '—'}`,
    d.slack_posted ? 'Slack: posted by API' : (d.slack_error ? 'Slack error: ' + d.slack_error : 'Slack: n/a')
].join('\n');

node.status({fill: ok ? 'green' : 'red', shape: 'dot', text: ok ? 'ok' : 'fail'});

// API already posts Slack when post_slack=true — only alert on hard failure
if (ok) {
    msg.payload = d;
    return [null, msg];
}
msg.headers = {
    Authorization: 'Bearer ' + (global.get('SLACK_TOKEN') || global.get('SLACK_BOT_TOKEN') || env.get('SLACK_BOT_TOKEN') || ''),
    'Content-Type': 'application/json; charset=utf-8'
};
msg.payload = {
    channel: global.get('SLACK_CHANNEL_ERRORS') || '#scraper-errors',
    text: '⚠️ *Ops Digest failed*\n' + text
};
msg.url = 'https://slack.com/api/chat.postMessage';
return [msg, null];
